delete from WFL_TRD_FIN_PRODUCT_DEAL_TOTAL 
where (WORKFLOW_ID is null or WORKFLOW_ID = '')
    and BUSI_TYPE = #{busiType}

    and FINPROD_TYPE2 = #{finProdType2}

delete from WFL_STL_PAY_ORDERS 
where (WORKFLOW_ID is null or WORKFLOW_ID = '')
and TRADE_ID in 
(select TOTLE_TRADE_ID from WFL_TRD_FIN_PRODUCT_DEAL_TOTAL 
where (WORKFLOW_ID is null or WORKFLOW_ID = '')
    and BUSI_TYPE = #{busiType}

    and FINPROD_TYPE2 = #{finProdType2}

)

delete from WFL_PA_TRD_FIN_DEAL_TOTAL 
where (WORKFLOW_ID is null or WORKFLOW_ID = '')
and TOTLE_TRADE_ID in 
(select TOTLE_TRADE_ID from WFL_TRD_FIN_PRODUCT_DEAL_TOTAL 
where (WORKFLOW_ID is null or WORKFLOW_ID = '')
    and BUSI_TYPE = #{busiType}

    and FINPROD_TYPE2 = #{finProdType2}

)

delete from WFL_TRD_PRODUCT_DEAL 
where (WORKFLOW_ID is null or WORKFLOW_ID = '')
    and BUSI_TYPE = #{busiType}

    and FINPROD_TYPE2 = #{finProdType2}

mapper.select:
 T1
WHERE
T1.PORTFOLIO_ID = #{ portfolioId}
AND T1.SEC_ACCT_ID = #{ secAcctId}
AND T1.FINPROD_ID = #{ finprodId}
AND T1.BRANCH = #{ branch}
AND T1.HODING_TYPE = #{ hodingType}
AND T1.CDATE <= #{cdate}
and not exists (select 1 from PTL_SEC_POSITION T2 where  T2.PORTFOLIO_ID = T1.PORTFOLIO_ID
    AND T2.SEC_ACCT_ID   = T1.SEC_ACCT_ID
    AND T2.FINPROD_ID    = T1.FINPROD_ID
    AND T2.BRANCH        = T1.BRANCH
    AND T2.HODING_TYPE   = T1.HODING_TYPE
    AND T2.CDATE         <= #{cdate}
    AND T2.CDATE > T1.CDATE
)
